import pathlib,json,re
p=pathlib.Path('/home/appontrack/.ontrack-saas/voice-lab')
files=[]
if p.is_dir():
 for item in sorted(p.glob('owner-*.json')):
  match=re.fullmatch(r'owner-(\d+)\.json',item.name)
  if match and item.is_file() and not item.is_symlink():
   try:
    data=json.loads(item.read_text());keys=data.get('keys',{})
    files.append({'uid':int(match.group(1)),'saved_google':bool(keys.get('google')),'saved_fish':bool(keys.get('fish'))})
   except Exception: files.append({'uid':int(match.group(1)),'bad_file':True})
print(json.dumps({'owner_files':files,'total':len(files)},separators=(',',':')))
